#nullable enable
class C
{
    bool M0(object obj) => false;

    void M1(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is null or false
            ? x.ToString() // 1
            : y.ToString();
    }

    void M2(C? c)
    {
        int x, y;
        _ = c?.M0(x = y = 0) is not (true or null)
            ? x.ToString()
            : y.ToString(); // 2
    }
}

